#[Route('/seats/{id}/book', methods: ['POST'])]
public function book(Seat $seat, EntityManagerInterface $em): JsonResponse
{
    if ($seat->isBooked()) {            // 1. check first
        return $this->json(['error' => 'Seat taken'], 409);
    }

    $seat->bookFor($this->getUser());   // 2. then change
    $em->flush();

    return $this->json(['ok' => true]);
}

#[Route('/seats/{id}/book', methods: ['POST'])]
public function book(int $id, EntityManagerInterface $em): JsonResponse
{
    $changed = $em->createQuery(
        'UPDATE App\Entity\Seat s SET s.bookedBy = :user
         WHERE s.id = :id AND s.bookedBy IS NULL'
    )->execute(['user' => $this->getUser(), 'id' => $id]);

    if ($changed === 0) {               // someone else got there first
        return $this->json(['error' => 'Seat taken'], 409);
    }

    return $this->json(['ok' => true]);
}
